using System.Reflection;
using System.Runtime.Loader;
using System.Text.Json;
using AlFalah.Application.IntelligentTimetable;
using AlFalah.Domain.Entities;
var dllRoot = args[0];
AssemblyLoadContext.Default.Resolving += (_, name) => {
    var path = Path.Combine(dllRoot, name.Name + ".dll");
    return File.Exists(path) ? AssemblyLoadContext.Default.LoadFromAssemblyPath(path) : null;
};
var tests = AssemblyLoadContext.Default.LoadFromAssemblyPath(Path.Combine(dllRoot, "AlFalah.Tests.dll"));
var fixture = tests.GetType("AlFalah.Tests.Timetables.TimetableReviewPhase7Tests", true)!;
var method = fixture.GetMethod("Context", BindingFlags.Static | BindingFlags.NonPublic)!;
var c = (TimetableValidationContext)method.Invoke(null, null)!;
var r = c.Requirements.Single();
r.Rooms.Add(new SubjectRoomRequirement {RoomId=1, IsPreferred=true});
r.Rooms.Add(new SubjectRoomRequirement {RoomId=2, IsPreferred=false});
c = c with { Rooms = [
    new TimetableRoom {Id=1,SchoolId=1,Name="Synthetic preferred"},
    new TimetableRoom {Id=2,SchoolId=1,Name="Synthetic alternative"}
]};
var generator = new TimetableGenerationEngine();
var validator = new TimetableValidationEngine();
var generated = generator.Generate(c, CancellationToken.None);
c.Timetable.Entries.Single().RoomId = 1;
var preferredFindings = validator.Evaluate(c).Where(x=>x.Detail=="required-room").Select(x=>new {RuleCode=x.RuleCode.ToString(),Severity=x.Severity.ToString(),x.Detail}).ToArray();
c.Timetable.Entries.Single().RoomId = 2;
var alternativeFindings = validator.Evaluate(c).Where(x=>x.Detail=="required-room").ToArray();
Console.WriteLine(JsonSerializer.Serialize(new {
    SyntheticOnly=true,
    AllowedRooms=new[]{1,2},PreferredRoom=1,
    GeneratedRooms=generated.Select(x=>x.RoomId).ToArray(),
    PreferredRoomFindings=preferredFindings,
    AlternativeRoomRequiredErrors=alternativeFindings.Length,
    NoDatabaseOrServicePersistence=true
}));
if (generated.Any(x=>x.RoomId!=2) || preferredFindings.Length!=1 || alternativeFindings.Length!=0) Environment.Exit(2);
